import type { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'Minimal Next.js 16.3 app',
  description: 'The smallest correct App Router app, with one dynamic route.',
};

// The root layout is required and must render <html> and <body>.
// `LayoutProps<'/'>` is a global type generated by `next dev`, `next build`
// or `next typegen`. It needs no import.
export default function RootLayout({ children }: LayoutProps<'/'>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}
